from book import Chapter
c=Chapter('18')
c.src('SEED-R10-0',0,replacements=[('其实这种算力和存储资源在提供AI推理的收费服务上和在用户导出和收回数据上的资源分配的区别对待，更在意自己赚钱的业务，而不在意用户的权益','如果算力和存储资源在提供 AI 推理收费服务时得到优先投入，而用户导出和收回数据却始终排在后面，这种资源分配的区别对待，就反映了服务方更在意什么'),('第一件事就是在新机制','第一件事，就是在新机制'),('REA(reverse engining anything)','REA，也就是逆向理解和接回已有系统的设想'),('就是为了吧所有用户的属于自己的数据','就是为了把所有用户属于自己的数据')])
c.add('''一个人能够在某个平台上查看自己的资料，并不等于他已经能够完整地支配这些资料。他可能只能通过平台规定的界面浏览，不能把历史记录带到另一个工具中；可以找到几条消息，却很难把围绕一个问题、跨越不同年份的思考连在一起；停止订阅或者更换设备之后，原本熟悉的工作方式也可能随之中断。

这里被分割的，不只是一个个文件。一个人的知识、偏好、交往和创造，正在被拆散到不同服务的账户里。每一个服务都知道其中一部分，而本人反而需要挨个寻找、申请导出、重新整理，才能接近自己的完整经历。

新框架的第一步，就是让这些内容重新回到个人可以选择工具、保存副本、安排使用方式的空间中。这个空间可以分布在本地和云端，但控制关系要围绕这个人建立。''')
c.heading('个人数字空间，为什么也是个人能力的一部分')
c.src('R46621',0,start='除了数据和代码',end='从而构建出完全不同的权利义务体系，集体决策的权力分配，社会组织形式和经济政治社会制度。',replacements=[('还包括在咱们做这个项目过程当中，所有的研究过程、沟通过程，都希望用这个方式，统一用这新框架给记录下来','还包括研究过程、沟通过程，都可以用同一套框架记录下来'),('从现在的 AI 发展也能看出来','从个人智能代理的发展方向也可以看出'),('实际上将来可能有了 Agent 这个接口之后，它实际上就是把所有这些都接管了','将来通过个人 Agent 这个接口，就有可能把这些分散的访问方式连接起来'),('而我们这新框架呢，实际上在这种新框架接管之下呢，实际上是把你自己整个这个用户这个人，他不光是说他用到的代码数据','在这个框架中，个人能够保存的，不仅是自己用到的代码和数据'),('连他交流过程、人生活的这个轨迹','还有交流过程、生活轨迹'),('凡是只要留下了数字印记的','凡是留下了数字印记、本人希望保留的内容'),('都记录了下来','都可以按本人选择记录下来'),('这个用户的代理节点清楚关于自己的所有兴趣爱好理念诉求以及权益权利和义务以及我所在这个世界上和其他人的关系等等等等','个人代理可以逐步理解自己的兴趣、爱好、理念、诉求、权益、义务，以及与其他人的关系'),('形成充分平等充分理性的博弈','不断接近更平等、更充分理性的博弈')])
c.add('''一个具体的例子是反复讨论同一个问题。人在不同时间、不同工具中提出的想法，并不总是重复。有时是在补充条件，有时是在回应别人，有时是在发现自己原来的解释不够好。只留下最新的结论，个人 AI 很难理解这个人为什么作出这样的选择；只保留所有文件，却没有来源和关系，也很难从大量资料中找出真正有用的部分。

因此，个人数字空间需要同时保留内容与关系。原话是什么，别人怎样回应，自己接受了什么、拒绝了什么，哪些地方仍在思考，都可以作为不同的记录存在。个人后来改变看法，也不需要把过去伪装成从未发生过。这使记忆能够支持学习，而不是把一个人固定在某个过去的版本里。''')
c.heading('隐私背后的权力关系')
c.src('R54886',31,32,replacements=[('而且，传统的人与人之间、人与国家之间所谓的隐私和安全问题，也就不再存在了','由此还可以追问，传统的人与人之间、人与国家之间的隐私和安全问题，究竟有多少来自权力关系'),('也就是所谓的保护隐私，都是因为怕','以及保护隐私的强烈需要，很多时候是因为怕'),('实际上，安全和隐私都是这个问题','我认为，权力关系是理解安全和隐私问题的一条重要线索'),('如果双方对等，并且互相绝对信任，就不再存在隐私问题了','设想双方完全对等，并且互相绝对信任，知道自己的信息不会被用来伤害自己，那么许多防御性的隐瞒就失去了理由')])
c.src('R54886',33,34,replacements=[('你也注意到了：',''),('是成正比的','往往是相互影响的'),('双方了解得越多，就越有可能形成合作','双方越能在信任的条件下了解对方，就越有可能形成合作'),('个体都非常害怕','个体往往会害怕')])
c.src('R54886',35,replacements=[('互相之间没有隐私，对吧？','更愿意向对方开放自己的生活。'),('如果有人认为有隐私，那么这种隐私在大多数情况下，是认为对方会伤害自己','对于必须隐瞒的信息，一个值得追问的原因，是担心对方会伤害自己'),('实际上，如果不会对对方造成伤害，那么从原理上讲，在任何情况下都并不会产生信息上的隔阂。产生隔阂的原因，实际上还是在于种种误解或不理解','如果信息被理解之后不会造成伤害，那么由防范和误解产生的信息隔阂，就有了可以减少的条件')])
c.add('''这个问题的重点，是谁能够利用信息做什么。一个普通员工把工作中的困难说出来，可能担心考核和职位受到影响；管理者却能够收集他的工作数据，又不让他知道这些数据被怎样使用。在这样的关系中，要求员工“充分共享”，很容易只是让单向透明变得更加彻底。

如果规则、资源和决策由共同参与者掌握，错误可以被研究，贡献可以被承认，信息的提供也能够帮助提供者改善处境，那么分享的动机就会不同。我们所要改变的，是让人不得不依靠隐瞒来保护自己的那些条件。''')
c.src('R54886',40,start='我所设想的这种新制度',end='因为任何隐瞒都会降低整个系统的运行效率和决策正确的概率。',replacements=[('任何一个参与者，都不可能获得过度的个体资源，也不可能获得更大的超过其认知判断水平的决策权重','在这种设计中，个人资源要与实际需要相联系，决策影响要与相应领域的判断和反馈相联系'),('那么这些个体在其日常活动中的所有信息和所有想法以及所有行为','如果这些条件逐步实现，那么个体日常活动中的信息、想法和行为'),('都没有必要对其他个体和团体进行隐瞒，因为任何隐瞒都会降低整个系统的运行效率和决策正确的概率','就可以更多地与其他个体和团体分享，因为相关信息的隐瞒，会使共同判断失去原本可能有用的材料')])
c.heading('全部记录与全部公开之间，需要什么联系')
c.add('''“我可以完整地保留自己的经历”和“所有人必须看见我的全部经历”，是两个不同的安排。一个人为了自己学习而保存的日记，可以首先属于他的个人空间；其中某个想法进入共同研究时，再把需要共享的部分带入公共知识。个人可以拥有完整记忆，而共同体不必因此得到无条件查看他的生活的权力。

这与充分共享的方向并不冲突。共享需要的是对共同任务有用的内容，以及使相关判断能够成立的依据。对于封装在对象内部、没有外部影响的过程，没有必要仅仅因为技术能够记录，就要求每一个人公开。

例如，一个人对某项服务提出改进意见，可以公开问题、复现步骤和需要解决的影响，却不必同时公开与这个问题无关的私人通信。随着信任和合作程度提高，他可以愿意提供更多材料；这种开放应该表现为掌控能力增加之后的选择，而不是掌控能力消失之后的服从。''')
c.src('R54949',0,start='构造一个分布式的去中心化的多用户身份系统',end='实现本项目的终极vision。',replacements=[('这个热路径库中的所有数据和代码','知识与能力库中的数据和代码'),('这个热路径库的所有具有主动操作性质的用户','其中具有主动操作性质的用户'),('才能支持这个项目不会落入威权商业或政治组织的控制，实现本项目的终极vision','才能支持个人与共同组织保持自主，防止这些能力重新落入少数权威的控制')])
c.heading('可追溯的记忆，如何支持持续变化的人')
c.src('R34499',1,2,replacements=[('其价值并不是体现在数据的访问效率上，也不在代码的调用和串联效率上，而在','我关注的价值，在于'),('具有可寻址防篡改可验证的记录功能','提供可寻址、可检查修改、可验证的记录功能'),('取决于','不仅取决于'),('这决定了','这会影响')])
c.add('''在技术上，内容寻址让取得的内容可以与已知标识进行核对，而这个标识并不规定内容必须存放在哪一家公司。身份和存放位置能够分开，是个人保留副本、改变服务提供者的重要基础。[IPLD 的内容寻址说明](https://ipld.io/docs/intro/hello-world/)

但是，可核验的记录也要与实际权限配合。给私人文件计算一个内容标识，不会自动使文件加密；把网络传输加密，也不等于接收者看不到内容。公共内容寻址网络还可能暴露访问和提供内容的线索，因此个人数据需要专门的内容加密、密钥控制和访问安排。[IPFS 的隐私与加密说明](https://docs.ipfs.tech/concepts/privacy-and-encryption/)

这些安排的目的，是让记忆跟随个人，而不是让个人被记忆困住。过去的一条观点可以继续作为历史存在，现在的立场可以清楚地指向新的表达。曾经给某个工具的使用权限，可以在以后改变；已经公开传播的副本，则需要如实承认它的存在，不能用界面上的一个删除按钮假装所有人都已经忘记。

当一个人能够保存、理解、修正和带走自己的资料时，他才真正拥有参与共同网络的基础。否则，所谓共同智能仍然要依赖几个掌握记忆入口的组织，个人只能把越来越多的经历交出去，再等待别人决定如何把这些经历还给自己。''')
c.add('''个人数据主权因此不只是一个文件下载功能。它是一个人能否持续拥有自己的知识、工具和参与能力的问题。由此出发，最初的云存储也就不必只是出售硬盘空间：它可以成为一个人把数字生活重新连起来、逐步建立共同合作关系的起点。''')
c.polish([('将原本分布在不同软件和服务的商业巨头所营造的信息孤岛中拿回来，我之前提到的类似于REA，也就是逆向理解和接回已有系统的设想的逆向收回所有个人信息放到新框架中的方案，就是为了把所有用户属于自己的数据，从传统商业巨头的手中夺回来。', '把原本分散在不同商业软件和服务的信息孤岛中的个人资料拿回来。REA，也就是逆向理解和接回已有系统的设想，要把这些个人信息收回，放到新的框架中，让所有用户重新掌握属于自己的数据。')])
c.save({'central_question':'数据主权为什么与隐私、平等和共同知识同时相关','reasoning':'服务权力差→个人数字空间→隐私的关系条件→记录与披露分离→内容身份和权限→持续改变与迁移','examples':['跨平台历史讨论','员工向管理者提供数据','私人日记与公开研究','服务故障复现与私人通信'],'objections':['记录天然等于监控','充分共享等于强制公开全部','计算哈希就完成隐私保护','保留过去等于冻结现在'],'voice':'保留作者REA、人生记录、隐私关系及两类资源论述；对强断言保留理论条件并列入实质改动核对','status':'需全书终校：核对隐私命题条件化是否忠实，绝不将此改写标成作者已批准的新立场'})
